// Application source, unchanged
n = write(1, "hi\n", 3);

// Linux guest: libc puts SYS_write in rax and
// executes the syscall instruction. The CPU switches
// to kernel mode, runs entry code (and swaps page
// tables if KPTI is on), then calls the write handler.

// Unikraft: the shim defines the handler as a C function
// (excerpt, lib/posix-fdio/fd-shim.c)
UK_SYSCALL_R_DEFINE(ssize_t, write, int, fd,
                    const void *, buf, size_t, count)
{
    ssize_t r;
    union uk_shim_file sf;
    switch (uk_fdtab_shim_get(fd, &sf)) {
    case UK_SHIM_OFILE:
        r = uk_sys_write(sf.ofile, buf, count);
        uk_ofile_release(sf.ofile);
        break;
    default:
        r = -EBADF;
    }
    return r;
}

/* Unikraft: every allocator implements struct uk_alloc.
 * Callers choose the backend explicitly. */
static inline void *uk_malloc(struct uk_alloc *a, __sz size)
{
    if (unlikely(!a)) {
        errno = ENOMEM;
        return __NULL;
    }
    return uk_do_malloc(a, size);  /* via a's function pointers */
}

/* plain malloc() in the application goes to the default
 * allocator chosen at configure time (buddy, TLSF,
 * tinyalloc, mimalloc, ...). */
